-- Ограничения production_day, составной ID и decimal(18,3). Отрицательное исходное число отвергается даже при округлении к нулю.
WITH p AS (SELECT entity_id,try(json_parse(payload)) AS j FROM {{target:oil_stg__v_event_parsed}} WHERE event_type='production_day'), v AS (SELECT entity_id,json_extract_scalar(j,'$.well_id') AS well_id,json_extract_scalar(j,'$.production_date') AS production_date,json_extract_scalar(j,'$.oil_tonnes') AS oil_tonnes,json_extract_scalar(j,'$.status') AS status FROM p) SELECT count(*) AS n FROM v WHERE well_id IS NULL OR NOT regexp_like(well_id,'^[A-Za-z0-9_-]+$') OR production_date IS NULL OR NOT regexp_like(production_date,'^[0-9]{4}-[0-9]{2}-[0-9]{2}$') OR try_cast(production_date AS date) IS NULL OR oil_tonnes IS NULL OR NOT regexp_like(oil_tonnes,'^[+-]?([0-9]+([.][0-9]*)?|[.][0-9]+)([eE][+-]?[0-9]+)?$') OR try_cast(oil_tonnes AS decimal(18,3)) IS NULL OR (substr(oil_tonnes,1,1)='-' AND regexp_like(regexp_extract(oil_tonnes,'^[+-]?([^eE]+)',1),'[1-9]')) OR status IS NULL OR status NOT IN ('ACTIVE','INACTIVE') OR entity_id IS DISTINCT FROM (well_id || '_' || replace(production_date,'-',''));
